def e(s):return escape(str(s),quote=True)
def icon(name='arrow-up-right'):return f'<i data-lucide="{name}" aria-hidden="true"></i>'
def link(href,text,kind='text-link'):return f'<a class="{kind}" href="{e(href)}">{text}{icon()}</a>'
def image(src,alt,cls='',eager=False):return f'<img src="{e(src)}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def canon(filename):
 routes={'index.html':'','manufacturing.html':'factory-tour','quality.html':'quality-delivery','company.html':'about-us','buyer-questions.html':'qa'}
