def detail_capacity(d):
 units=d.get('unitReference','')
 return d['capacity']+(' / '+units+(' per container' if re.search(r'\bx\s*\d+',d['capacity']) else '') if units else '')
def model_capacity(m):return ' + '.join(detail_capacity(x) for x in m['model']['details'])
def model_title(m):return m['model']['code']+(' · '+m['model'].get('variant','') if m['model'].get('variant') else '')
