for m in DATA['models']:
 capacity_ml=[float(re.search(r'([\d,]+(?:\.\d+)?)\s*ml',d['capacity'],re.I)[1].replace(',','')) for d in m['model']['details'] if re.search(r'([\d,]+(?:\.\d+)?)\s*ml',d['capacity'],re.I)]
 INDEX.append({'id':m['id'],'name':model_title(m),'capacity':model_capacity(m),'capacityMl':capacity_ml,'size':m['model']['size'],'material':' / '.join(m['model']['materials']),'lid':LIDS[m['lidType']][1],'image':m['image'],'url':LIDS[m['lidType']][0]+'#'+m['id'],'category':'storage'})
for s in DATA['catalog']['series']:
 if s['category']!='storage':
  filename={'cookware':'cookware.html','plates':'serving-plates.html','kettles':'kettles.html'}[s['category']]
  capacity=s['specs'][0]['value'] if s['category']=='kettles' else next((x['value'] for x in s['specs'] if x['label']=='Capacity'),'Confirm capacity by model')
  size='Confirm dimensions by model' if s['category']=='kettles' else s['specs'][0]['value']
  capacity_ml=[float(value)*1000 for value in re.findall(r'\d+(?:\.\d+)?',capacity)] if s['category']=='kettles' else []
  INDEX.append({'id':s['id'],'name':s['title'],'capacity':capacity,'capacityMl':capacity_ml,'size':size,'material':next(x['value'] for x in s['specs'] if x['label']=='Body material'),'lid':next(x['value'] for x in s['specs'] if x['label']=='Lid material'),'image':s['images'][0]['src'],'url':filename+'#'+s['id'],'category':s['category']})
SPECIAL=json.loads((ROOT/'data/special-lids.json').read_text(encoding='utf-8'))
for item in SPECIAL:
 amount=re.search(r'([\d,]+)\s*ml',item['capacity'])
 INDEX.append({'id':item['id'],'name':item['title'],'capacity':item['capacity'],'capacityMl':[int(amount[1].replace(',',''))] if amount else [],'size':item.get('size','Confirm the selected model and lid'),'material':'304 / 316L / Titanium, configuration confirmed by model','lid':item['lids'],'image':item['image'],'url':'storage-special.html#'+item['id'],'category':'storage','additionalFamily':True})
